<script setup lang="ts">
import {ref,watch,nextTick} from 'vue'
import {personState} from './people'
const props=defineProps<{project:Record<string,any>,zoom:number,selectedId?:string,disabled?:boolean,mode?:string}>()
const emit=defineEmits(['select','changed','added'])
const selected=ref(''),container=ref<HTMLElement|null>(null)
watch(()=>props.selectedId,async value=>{selected.value=value||'';await nextTick();const el=container.value?.querySelector(`[data-id="${selected.value}"]`);el?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})})
let drag:any=null
function point(e:PointerEvent){const r=(e.currentTarget as HTMLElement).getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
function down(e:PointerEvent){if(props.disabled)return;const start=point(e);const target=e.target as HTMLElement;const box=target.closest('[data-id]') as HTMLElement|null;selected.value=box?.dataset.id||'';emit('select',selected.value);const a=props.mode==='select'?props.project.annotations.find((a:any)=>a.id===selected.value):undefined;drag={start,a,before:a?{...a}:null,resize:target.classList.contains('resize'),clientX:e.clientX,clientY:e.clientY,left:container.value?.scrollLeft,top:container.value?.scrollTop};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(props.disabled)return;if(!drag)return;if(props.mode==='pan'&&container.value){container.value.scrollLeft=drag.left-(e.clientX-drag.clientX);container.value.scrollTop=drag.top-(e.clientY-drag.clientY);return}if(!drag.a)return;const p=point(e),dx=p.x-drag.start.x,dy=p.y-drag.start.y;const a=drag.a,b=drag.before;if(drag.resize){a.w=Math.max(.005,Math.min(1-a.x,b.w+dx));a.h=Math.max(.005,Math.min(1-a.y,b.h+dy))}else{a.x=Math.max(0,Math.min(1-a.w,b.x+dx));a.y=Math.max(0,Math.min(1-a.h,b.y+dy))}a.confirmed=false;emit('changed',a.id)}
function up(e:PointerEvent){if(props.disabled){drag=null;return;}if(!drag)return;const p=point(e);if(props.mode==='add'&&!drag.a&&Math.abs(p.x-drag.start.x)>.01&&Math.abs(p.y-drag.start.y)>.01){const a={id:crypto.randomUUID().slice(0,12),x:Math.min(p.x,drag.start.x),y:Math.min(p.y,drag.start.y),w:Math.abs(p.x-drag.start.x),h:Math.abs(p.y-drag.start.y),description:'',kind:'character',characterId:'',confirmed:false};props.project.annotations.push(a);selected.value=a.id;emit('select',a.id);emit('added')}drag=null}
</script>
<template><div ref="container" class="image-scroll"><div class="painting" :style="{width:zoom+'%'}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="drag=null"><img :src="project.image" draggable="false"><div v-for="(a,i) in project.annotations" :data-id="a.id" class="editable-box" :class="[{selected:selected===a.id},personState(project,a).key]" :style="{left:a.x*100+'%',top:a.y*100+'%',width:a.w*100+'%',height:a.h*100+'%'}"><span class="box-label">{{Number(i)+1}} · {{personState(project,a).label}}</span><span v-if="mode==='select'" class="resize"/></div></div></div></template>
<style scoped>.editable-box{position:absolute;border:2px solid #bc733d;color:white;background:#d9943c22;font-size:14px;line-height:20px;cursor:move}.editable-box.confirmed{border-color:#238052;background:#23805218}.editable-box.unnamed{border-color:#7c8583;background:#7c858318}.editable-box.pending,.editable-box.review{border-color:#b67b1b;background:#b67b1b18}.editable-box.selected{outline:3px solid #406ec0;outline-offset:3px}.box-label{position:absolute;top:0;left:0;white-space:nowrap;background:#8e651d;color:white;font-size:11px;padding:1px 4px}.confirmed .box-label{background:#238052}.unnamed .box-label{background:#6d7774}.resize{position:absolute;bottom:-5px;right:-5px;width:12px;height:12px;background:#31594b;cursor:nwse-resize}.image-scroll{max-height:650px;overflow:auto}</style>
